onMounted(() => window.addEventListener('keydown', e => { if(['ArrowRight',' ','PageDown'].includes(e.key)){e.preventDefault();go(1)} if(['ArrowLeft','PageUp'].includes(e.key)){e.preventDefault();go(-1)} if(e.key==='Home')current.value=0;if(e.key==='End')current.value=slides.length-1 }))
